const localeMap=new Map();
localeEntries.forEach(entry=>{[entry[0],entry[1],entry[2]].forEach(text=>{if(text)localeMap.set(text,entry)})});
function tr(value){const entry=localeMap.get(value.trim());return entry?value.replace(value.trim(),entry[window.TT_LOCALE==='en'?2:1]):value}
window.tr=tr;
const localeOrigins=new WeakMap();
function localize(root=document.body){
 const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
 while(node=walk.nextNode()){if(node.parentElement.closest('script,style,[data-copy],.language-switch,#toast'))continue;
  const current=node.nodeValue;const previous=localeOrigins.get(node);const entry=previous&&[previous[0],previous[1],previous[2]].includes(current.trim())?previous:localeMap.get(current.trim());
  if(entry){localeOrigins.set(node,entry);const next=current.replace(current.trim(),entry[window.TT_LOCALE==='en'?2:1]);if(next!==current)node.nodeValue=next}
 }
 root.querySelectorAll('[aria-label]').forEach(el=>{let value=el.getAttribute('aria-label');let next=tr(value);if(value.startsWith('播放或暂停：')||value.startsWith('Play or pause: ')){const name=value.replace(/^(播放或暂停：|Play or pause: )/,'');next=(window.TT_LOCALE==='en'?'Play or pause: ':'播放或暂停：')+tr(name)}if(value.startsWith('放大查看：')||value.startsWith('Expand: ')){next=(window.TT_LOCALE==='en'?'Expand: ':'放大查看：')+tr(value.replace(/^(放大查看：|Expand: )/,''))}if(value.startsWith('视频时长 ')||value.startsWith('Duration '))next=(window.TT_LOCALE==='en'?'Duration ':'视频时长 ')+value.split(' ').pop();if(next!==value)el.setAttribute('aria-label',next)});
}
window.TT_localize=localize;
const sourceCopies={"toast-title": "小小观察员，<br>今天戴蓝色眼镜", "toast-deck": "购物车还在身后，镜头前已经有了今天的主角。", "toast-body": "超市里的购物车排成一行。小朋友戴着一副蓝色圆框眼镜，站在车旁，朝镜头看过来。圆圆的镜框，让这次普通的出门多了一个值得记住的细节。", "picnic-title": "客厅里，<br>响起一阵小掌声", "picnic-body": "小朋友坐在地砖上，双腿向两侧展开。两只小手在身前拍到一起，笑容也跟着出现。", "shop-title": "坐骑已就位，<br>小骑手指向镜头", "shop-body": "小朋友坐在木雕牛背上，一只手扶着坐骑，另一只手朝镜头伸过来。她笑了笑，又转头看向旁边。", "music-title": "这份开心，<br>已经藏不住了", "music-body": "她坐在垫子上，面对镜头笑得眯起眼睛。嘴里还含着绿色的食物，身体随着笑容向前倾，又坐了回来。"};
window.TT_defaultCopy=(key)=>{const tpl=document.createElement('template');tpl.innerHTML=sourceCopies[key];const walker=document.createTreeWalker(tpl.content,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode())n.nodeValue=tr(n.nodeValue);return tpl.innerHTML};
function languageChrome(){document.documentElement.lang=window.TT_LOCALE==='en'?'en':'zh-CN';document.title=window.TT_LOCALE==='en'?'The Toddler Times — The Family Edition':'小小日常报 · 家庭影像特刊';document.querySelectorAll('[data-language]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.language===window.TT_LOCALE)));document.querySelector('.language-switch').setAttribute('aria-label',window.TT_LOCALE==='en'?'Language':'语言');localize()}
window.TT_languageChrome=languageChrome;
document.querySelectorAll('[data-copy]').forEach(el=>el.innerHTML=window.TT_defaultCopy(el.dataset.copy));
languageChrome();
const languageObserver=new MutationObserver(()=>localize());languageObserver.observe(document.body,{childList:true,subtree:true,characterData:true});
